--- 设置提示节点
---@param direction number 方向（1：左边，2：右边）
---@param text string 文本
function UIBattlingCardTipsNode:SetTips(direction, text, parent)
    local rectTransform = self.controller.transform:GetComponent(typeof(CS.UnityEngine.RectTransform))
    if direction == 1 then
        -- 把预制体防止parent下面，然后设置layout参数
        self.controller.transform:SetParent(parent)
        rectTransform.pivot = Vector2.New(0.5,0.5)
        rectTransform.localPosition = Vector3.zero
        rectTransform.localScale = Vector3.one
        rectTransform.anchoredPosition = BattleInfo:IsPVP() and PVPOffset or PVEOffset
        -- 使用左侧的文本
        self.Root_Direction.localScale = Vector3.New(-1,1,1)
        KTool.SetActive(self.Txt_Left, true)
        KTool.SetActive(self.Txt_Right, false)
        self.Txt_Left.text = text
    elseif direction == 2 then
        -- 修改layout
        self.controller.transform:SetParent(parent)
        rectTransform.anchorMin = Vector2.New(0,0)
        rectTransform.anchorMax = Vector2.New(0,0)
        rectTransform.pivot = Vector2.New(1,0)
        rectTransform.localPosition = Vector3.zero
        rectTransform.localScale = Vector3.one
        rectTransform.anchoredPosition = BattleInfo:IsPVP() and PVPOffset or PVEOffset
        -- 设置使用右侧的文本
        self.Root_Direction.localScale = Vector3.New(1,1,1)
        KTool.SetActive(self.Txt_Left, false)
        KTool.SetActive(self.Txt_Right, true)
        self.Txt_Right.text = text
    end
end

function UIBattlingCardTipsNode:Show()
    self.CanvasGroup_Root:DOFade(1, 0.5)
end

function UIBattlingCardTipsNode:Hide()
    self.CanvasGroup_Root:DOFade(0, 0.5)
end

